INSERT INTO `games_test` VALUES (10090,'Call of Duty: World at War','Treyarch',1999,'Action','2008-11-18','Call of Duty is back, redefining war like you\'ve never experienced before. Building on the Call of Duty 4®: Modern Warfare engine, Call of Duty: World at War immerses players into the most gritty and chaotic WWII combat ever experienced.',18,'..\\..\\images\\call_of_duty__world_at_war.jpg'),(45760,'Ultra Street Fighter IV','Capcom',2999,'Action','2014-08-07','The world’s greatest fighting game evolves to a whole new level with Ultra Street Fighter IV.',12,'..\\..\\images\\ultra_street_fighter_iv.jpg'),(113400,'APB Reloaded','Little Orbit',0,'Action, Massively Multiplayer, Free To Play','2011-12-06','The world’s first and premier Action MMO Third Person Shooter allows you to choose between two sides of the law. Play as Enforcer or Criminal, customize your gear for the task at hand and hit the streets and play how you want in a city filled with more action this side of a Hollywood blockbuster.',18,'..\\..\\images\\apb_reloaded.jpg'),(204360,'Castle Crashers','The Behemoth',1499,'Action, Adventure, Casual, Indie, RPG','2012-09-26','Hack, slash, and smash your way to victory in this award winning 2D arcade adventure from The Behemoth!',16,'..\\..\\images\\castle_crashers.jpg'),(209650,'Call of Duty: Advanced Warfare - Gold Edition','Sledgehammer Games, Raven Software',5999,'Action','2014-11-03','Call of Duty®: Advanced Warfare envisions a powerful future, where both technology and tactics have evolved to usher in a new era of combat for the franchise.Power Changes Everything.',18,'..\\..\\images\\call_of_duty__advanced_warfare___gold_edition.jpg'),(218620,'PAYDAY 2','OVERKILL - a Starbreeze Studio.',999,'Action, RPG','2013-08-13','PAYDAY 2 is an action-packed, four-player co-op shooter that once again lets gamers don the masks of the original PAYDAY crew - Dallas, Hoxton, Wolf and Chains - as they descend on Washington DC for an epic crime spree.',18,'..\\..\\images\\payday_2.jpg'),(230410,'Warframe','Digital Extremes',0,'Action, RPG, Free To Play','2013-03-25','Awaken as an unstoppable warrior and battle alongside your friends in this story-driven free-to-play online action game',18,'..\\..\\images\\warframe.jpg'),(236390,'War Thunder','Gaijin Entertainment',0,'Action, Massively Multiplayer, Simulation, Free To Play','2013-08-15','War Thunder is the most comprehensive free-to-play, cross-platform, MMO military game dedicated to aviation, armoured vehicles, and naval craft, from the early 20th century to the most advanced modern combat units. Join now and take part in major battles on land, in the air, and at sea.',12,'..\\..\\images\\war_thunder.jpg'),(245170,'Skullgirls 2nd Encore','Hidden Variable Studios',2499,'Action, Indie','2013-08-22','--Main Stage Game at Evo 2022!-- The ultimate Skullgirls experience: Featuring 14 hand-animated characters, fully voiced story mode, countless palettes, and unparalleled GGPO-based multiplayer netcode.',12,'..\\..\\images\\skullgirls_2nd_encore.jpg'),(250900,'The Binding of Isaac: Rebirth','Nicalis, Inc., Edmund McMillen',1499,'Action','2014-11-04','The Binding of Isaac: Rebirth is a randomly generated action RPG shooter with heavy Rogue-like elements. Following Isaac on his journey players will find bizarre treasures that change Isaac’s form giving him super human abilities and enabling him to fight off droves of mysterious creatures, discover secrets and fight his way to safety.',NULL,'..\\..\\images\\the_binding_of_isaac__rebirth.jpg'),(252950,'Rocket League','Psyonix LLC',0,'Action, Indie, Racing, Sports','2015-07-06','Rocket League is a high-powered hybrid of arcade-style soccer and vehicular mayhem with easy-to-understand controls and fluid, physics-driven competition. Rocket League includes casual and competitive Online Matches, a fully-featured offline Season Mode, special “Mutators” that let you change the rules entirely, hockey and...',3,'..\\..\\images\\rocket_league.jpg'),(262060,'Darkest Dungeon','Red Hook Studios',2499,'Indie, RPG, Strategy','2016-01-19','Darkest Dungeon is a challenging gothic roguelike turn-based RPG about the psychological stresses of adventuring. Recruit, train, and lead a team of flawed heroes against unimaginable horrors, stress, disease, and the ever-encroaching dark. Can you keep your heroes together when all hope is lost?',16,'..\\..\\images\\darkest_dungeon.jpg'),(273350,'Evolve Stage 2','Turtle Rock Studios',0,'Action, Free To Play','2015-02-10','Play Evolve for free with Evolve Stage 2! Evolve Stage 2 is a next-generation free multiplayer shooter featuring addictive 4v1 gameplay. One player-controlled monster must evade and outsmart a team of four uniquely skilled hunters.',16,'..\\..\\images\\evolve_stage_2.jpg'),(281990,'Stellaris','Paradox Development Studio',3999,'Simulation, Strategy','2016-05-09','Explore a galaxy full of wonders in this sci-fi grand strategy game from Paradox Development Studios. Interact with diverse alien races, discover strange new worlds with unexpected events and expand the reach of your empire. Each new adventure holds almost limitless possibilities.',7,'..\\..\\images\\stellaris.jpg'),(289070,'Sid Meier’s Civilization VI','Firaxis Games, Aspyr (Mac), Aspyr (Linux)',5999,'Strategy','2016-10-20','Expand your empire, advance your culture and go head-to-head against history’s greatest leaders. Will your civilization stand the test of time?',12,'..\\..\\images\\sid_meier_s_civilization_vi.jpg'),(290340,'Armello','League of Geeks',2499,'Adventure, Indie, RPG, Strategy','2015-09-01','Armello is a grim fairy-tale board game come to life, with every match combining deep, tactical card play, rich tabletop strategy and RPG elements. Leverage subterfuge, spells and careful strategy to wrangle control of the game\'s chaotic odds as you quest for the throne.',7,'..\\..\\images\\armello.jpg'),(291550,'Brawlhalla','Blue Mammoth Games',0,'Action, Indie, Free To Play','2017-10-17','An epic platform fighter for up to 8 players online or local. Try casual free-for-alls, ranked matches, or invite friends to a private room. And it\'s free! Play cross-platform with millions of players on PlayStation, Xbox, Nintendo Switch, iOS, Android &amp; Steam! Frequent updates. Over sixty Legends.',7,'..\\..\\images\\brawlhalla.jpg'),(292730,'Call of Duty: Infinite Warfare','Infinity Ward',5999,'Action, Adventure','2016-11-03','Infinite Warfare delivers three unique game modes: Campaign, Multiplayer, and Zombies.',18,'..\\..\\images\\call_of_duty__infinite_warfare.jpg'),(301520,'Robocraft','Freejam',0,'Action, Indie, Massively Multiplayer, RPG, Simulation, Free To Play','2017-08-24','Build insane, fully customisable robot battle vehicles that drive, hover, walk and fly in the free-to-play action game Robocraft. Add weapons from the future and jump in the driving seat as you take your creation into battle against other players online!',NULL,'..\\..\\images\\robocraft.jpg'),(304050,'Trove','gamigo US Inc.',0,'Action, Adventure, Casual, Massively Multiplayer, RPG, Free To Play','2015-07-09','Grab your friends, hone your blades, and set off for an epic procedurally generated adventure in Trove! Battle the Shadow in realms filled with dungeons and items created by your fellow players. Whether hunting treasure or building realms of your own, it’s never been this good to be square!',7,'..\\..\\images\\trove.jpg'),(304390,'FOR HONOR','Ubisoft Montreal, Ubisoft Quebec, Ubisoft Toronto, Blue Byte',2999,'Action','2024-03-14','Fight alone or with friends in For Honor, a third-person hero-based melee fighting game. Enter the chaos of war as a Knight, a Viking, a Samurai, a Wu Lin, or an Outlander. Fight in brutal PvP and team-oriented modes, or play the thrilling story campaign.',18,'..\\..\\images\\for_honor.jpg'),(310950,'Street Fighter V','CAPCOM Co., Ltd.',1999,'Action','2016-02-15','Experience the intensity of head-to-head battles with Street Fighter® V! Choose from 16 iconic characters, then battle against friends online or offline with a robust variety of match options.',12,'..\\..\\images\\street_fighter_v.jpg'),(311210,'Call of Duty: Black Ops III','Treyarch, Aspyr (Mac)',5999,'Action, Adventure','2015-11-05','Call of Duty®: Black Ops III Zombies Chronicles Edition includes the full base game plus the Zombies Chronicles content expansion.',18,'..\\..\\images\\call_of_duty__black_ops_iii.jpg'),(316010,'Magic Duels','Stainless Games Ltd.',0,'Free To Play, Strategy','2015-07-29','MORE CARDS. MORE STRATEGY. BIGGER STORY. Collect 1,300+ earnable cards, battle in 60+ single-player campaign missions, and emerge victorious in epic online duels.',12,'..\\..\\images\\magic_duels.jpg'),(323190,'Frostpunk','11 bit studios',2999,'Simulation, Strategy','2018-04-24','Frostpunk is the first society survival game. As the ruler of the last city on Earth, it is your duty to manage both its citizens and infrastructure. What decisions will you make to ensure your society\'s survival? What will you do when pushed to breaking point? Who will you become in the process?',16,'..\\..\\images\\frostpunk.jpg'),(331360,'Heavy Metal Machines','Hoplon',0,'Action, Casual, Free To Play, Indie, Sports','2018-09-19','Heavy Metal Machines is a one of a kind Free-to-Play Multiplayer Vehicular Combat game where players engage in 4v4 intense battles, controlling lethal vehicles in post-apocalyptic arenas.',7,'..\\..\\images\\heavy_metal_machines.jpg'),(357190,'ULTIMATE MARVEL VS. CAPCOM 3','CAPCOM CO., LTD.',2499,'Action','2017-03-06','Marvel and Capcom join forces to deliver the most frenetic 3 vs 3 tag battles ever with Ultimate Marvel VS Capcom 3. This release comes fully loaded, including all previous DLC, Marvel VS. Capcom : Official Complete Works.',12,'..\\..\\images\\ultimate_marvel_vs__capcom_3.jpg'),(359550,'Tom Clancy\'s Rainbow Six Siege','Ubisoft Montreal',1999,'Action','2015-12-01','Rainbow Six Siege X is the reference in tactical team shooters, where elite strategy and execution triumph. Enjoy free access to Quick Match, Unranked and Dual Front game modes with a selection of operators.',18,'..\\..\\images\\tom_clancy_s_rainbow_six_siege.jpg'),(374320,'DARK SOULS III','FromSoftware, Inc.',5999,'Action','2016-04-11','Dark Souls continues to push the boundaries with the latest, ambitious chapter in the critically-acclaimed and genre-defining series. Prepare yourself and Embrace The Darkness!',16,'..\\..\\images\\dark_souls_iii.jpg'),(377160,'Fallout 4','Bethesda Game Studios',1999,'RPG','2015-11-09','Bethesda Game Studios, the award-winning creators of Fallout 3 and The Elder Scrolls V: Skyrim, welcome you to the world of Fallout 4 – their most ambitious game ever, and the next generation of open-world gaming.',18,'..\\..\\images\\fallout_4.jpg'),(381210,'Dead by Daylight','Behaviour Interactive Inc.',1999,'Action','2016-06-14','Trapped forever in a realm of eldritch evil where even death is not an escape, four determined Survivors face a bloodthirsty Killer in a vicious game of nerve and wits. Pick a side and step into a world of tension and terror with horror gaming\'s best asymmetrical multiplayer.',18,'..\\..\\images\\dead_by_daylight.jpg'),(383980,'Rivals of Aether','Aether Studios',2999,'Indie','2017-03-28','RIVALS OF AETHER is an indie fighting game where warring civilizations summon the power of Fire, Water, Air, and Earth. Play with up to four players either locally or online.',7,'..\\..\\images\\rivals_of_aether.jpg'),(386360,'SMITE','Titan Forge Games',0,'Action, Adventure, Casual, Massively Multiplayer, RPG, Strategy, Free To Play','2015-09-08','Join 40+ million players in SMITE, the Battleground of the Gods! Wield Thor’s hammer, turn your foes to stone as Medusa, or flex your divine power as one of 100+ other mythological icons. Become a God and play FREE today!',12,'..\\..\\images\\smite.jpg'),(389730,'TEKKEN 7','BANDAI NAMCO Studios Inc.',3999,'Action, Sports','2017-06-01','Discover the epic conclusion of the long-time clan warfare between members of the Mishima family. Powered by Unreal Engine 4, the legendary fighting game franchise fights back with stunning story-driven cinematic battles and intense duels that can be enjoyed with friends and rivals.',16,'..\\..\\images\\tekken_7.jpg'),(397060,'Faeria','Abrakam Entertainment SA',1999,'Adventure, Indie, Massively Multiplayer, RPG, Strategy','2017-03-08','With its unique living board, Faeria is also the only card game where you can gain all 300 cards in less than 50 hours.',7,'..\\..\\images\\faeria.jpg'),(414340,'Hellblade: Senua\'s Sacrifice','Ninja Theory',2999,'Action, Adventure, Indie','2017-08-07','From the makers of Heavenly Sword, Enslaved: Odyssey to the West, and DmC: Devil May Cry, comes a warrior’s brutal journey into myth and madness. Set in the Viking age, a broken Celtic warrior embarks on a haunting vision quest into Viking Hell to fight for the soul of her dead lover.',18,'..\\..\\images\\hellblade__senua_s_sacrifice.jpg'),(480490,'Prey','Arkane Studios',2999,'Action, Adventure','2017-05-04','In Prey, you awaken aboard Talos I, a space station orbiting the moon in the year 2032. You are the key subject of an experiment meant to alter humanity forever – but things have gone terribly wrong. The space station has been overrun by hostile aliens and you are now being hunted.',18,'..\\..\\images\\prey.jpg'),(512900,'Streets of Rogue','Matt Dabrowski',1999,'Action, Adventure, Indie, RPG','2019-07-12','Fight, sneak, and hack your way through randomly generated cities. It\'s like Nuclear Throne meets Deus Ex, mixed with the anarchy of GTA. Rogue-lite meets immersive sim, and goes completely insane.',16,'..\\..\\images\\streets_of_rogue.jpg'),(513650,'Zula Europe','Madbyte Games',0,'Action, Free to Play, Massively Multiplayer',NULL,NULL,NULL,'..\\..\\images\\zula_europe.jpg'),(552990,'World of Warships','Wargaming Group Limited',0,'Action, Massively Multiplayer, Simulation, Strategy, Free To Play','2017-11-15','Immerse yourself in thrilling naval battles and assemble an armada of over 600 ships from the first half of the 20th century — from stealthy destroyers to gigantic battleships. Change the look of your ship, choose upgrades to suit your play style, and go into battle with other players!',12,'..\\..\\images\\world_of_warships.jpg'),(553850,'HELLDIVERS 2','Arrowhead Game Studios',3999,'Action','2024-02-08','The Galaxy’s Last Line of Offence. Enlist in the Helldivers and join the fight for freedom across a hostile galaxy in a fast, frantic, and ferocious third-person shooter.',18,'..\\..\\images\\helldivers_2.jpg'),(588650,'Dead Cells','Motion Twin',2499,'Action, Adventure, Indie','2018-08-06','Dead Cells is a roguelite, metroidvania inspired, action-platformer. You\'ll explore a sprawling, ever-changing castle... assuming you’re able to fight your way past its keepers in 2D souls-lite combat. No checkpoints. Kill, die, learn, repeat.',16,'..\\..\\images\\dead_cells.jpg'),(623990,'Tom Clancy\'s Rainbow Six Siege - Test Server','',NULL,'',NULL,NULL,NULL,'..\\..\\images\\tom_clancy_s_rainbow_six_siege___test_server.jpg'),(632360,'Risk of Rain 2','Hopoo Games',824,'Action, Indie','2020-08-11','Escape a chaotic alien planet by fighting through hordes of frenzied monsters – with your friends, or on your own. Combine loot in surprising ways and master each character until you become the havoc you feared upon your first crash landing.',12,'..\\..\\images\\risk_of_rain_2.jpg'),(753640,'Outer Wilds','Mobius Digital',1499,'Action, Adventure','2020-06-18','Named Game of the Year 2019 by Giant Bomb, Polygon, Eurogamer, and The Guardian, Outer Wilds is a critically-acclaimed and award-winning open world mystery about a solar system trapped in an endless time loop.',7,'..\\..\\images\\outer_wilds.jpg'),(838380,'DEAD OR ALIVE 6','KOEI TECMO GAMES CO., LTD.',5999,'Action','2019-02-28','DEAD OR ALIVE 6 is fast-paced 3D fighting game, produced by Koei Tecmo Games, featuring stunning graphics and multi-tiered stages that create a truly entertaining competitive experience.',16,'..\\..\\images\\dead_or_alive_6.jpg'),(858460,'Smite - Public Test','',NULL,'',NULL,NULL,NULL,'..\\..\\images\\smite___public_test.jpg'),(860510,'Little Nightmares II','Tarsier Studios',2999,'Adventure','2021-02-10','Little Nightmares II is the second game in a series that has thrilled and captivated millions of players worldwide since 2017. Now it’s your turn to try to survive this critically acclaimed entry in the most charming horror series ever made.',16,'..\\..\\images\\little_nightmares_ii.jpg'),(976310,'Mortal Kombat 11','NetherRealm Studios, QLOC, Shiver',4999,'Action','2019-04-23','Mortal Kombat is back and better than ever in the next evolution of the iconic franchise.',18,'..\\..\\images\\mortal_kombat_11.jpg'),(987350,'PlanetSide Arena','Daybreak Game Company',0,'Action, Free To Play, Massively Multiplayer, Early Access','2019-09-19','PlanetSide Arena servers will be shutting down on January 10, 2020. Read our dev letter to learn more.',16,'..\\..\\images\\planetside_arena.jpg'),(1057090,'Ori and the Will of the Wisps','Moon Studios GmbH',2999,'Action','2020-03-10','Play the critically acclaimed masterpiece. Embark on a new journey in a vast, exotic world where you’ll encounter towering enemies and challenging puzzles on your quest to unravel Ori’s destiny.',7,'..\\..\\images\\ori_and_the_will_of_the_wisps.jpg'),(1086940,'Baldur\'s Gate 3','Larian Studios',5999,'Adventure, RPG, Strategy','2023-08-03','Baldur’s Gate 3 is a story-rich, party-based RPG set in the universe of Dungeons &amp; Dragons, where your choices shape a tale of fellowship and betrayal, survival and sacrifice, and the lure of absolute power.',18,'..\\..\\images\\baldur_s_gate_3.jpg'),(1172470,'Apex Legends','Respawn',0,'Action, Adventure, Free To Play','2020-11-04','Apex Legends is the award-winning, free-to-play Hero Shooter from Respawn Entertainment. Master an ever-growing roster of legendary characters with powerful abilities, and experience strategic squad play and innovative gameplay in the next evolution of Hero Shooter and Battle Royale.',16,'..\\..\\images\\apex_legends.jpg'),(1194810,'Meet Your Maker','Behaviour Interactive Inc.',1999,'Action, Strategy','2023-04-04','Meet Your Maker is a building game of brutal expression and conquest. Unleash your inner evil genius in co-op or single-player to build the ultimate fortress of devious deathtraps, or take on those built by others in a high-stakes heist to steal resources essential for your survival.',16,'..\\..\\images\\meet_your_maker.jpg'),(1203220,'NARAKA: BLADEPOINT','24 Entertainment',0,'Action, Adventure, Massively Multiplayer','2021-08-11','Dive into the legends of the Far East in NARAKA: BLADEPOINT; team up with friends in fast-paced melee fights for a Battle Royale experience unlike any other. Find your playstyle with a varied cast of heroes with unique skills. More than 20 million players have already joined the fray, play free now!',12,'..\\..\\images\\naraka__bladepoint.jpg'),(1245620,'ELDEN RING','FromSoftware, Inc.',5999,'Action, RPG','2022-02-24','THE CRITICALLY ACCLAIMED FANTASY ACTION RPG. Rise, Tarnished, and be guided by grace to brandish the power of the Elden Ring and become an Elden Lord in the Lands Between.',16,'..\\..\\images\\elden_ring.jpg'),(1252330,'DEATHLOOP','Arkane Studios',5999,'Action','2021-09-13','DEATHLOOP is a next-gen FPS from Arkane Lyon, the award-winning studio behind Dishonored. In DEATHLOOP, two rival assassins are trapped in a mysterious timeloop on the island of Blackreef, doomed to repeat the same day for eternity.',18,'..\\..\\images\\deathloop.jpg'),(1282100,'REMNANT II','Gunfire Games',1999,'Action, Adventure, RPG','2023-07-25','REMNANT II® pits survivors of humanity against new deadly creatures and god-like bosses across terrifying worlds. Play solo or co-op with two other friends to explore the depths of the unknown to stop an evil from destroying reality itself.',18,'..\\..\\images\\remnant_ii.jpg'),(1284410,'GWENT: The Witcher Card Game','CD PROJEKT RED',0,'RPG, Strategy, Free To Play','2020-05-19','Command mighty Witcher-world heroes in epic online PvP card battles!',16,'..\\..\\images\\gwent__the_witcher_card_game.jpg'),(1332010,'Stray','BlueTwelve Studio',1799,'Adventure, Indie','2022-07-19','Lost, alone and separated from family, a stray cat must untangle an ancient mystery to escape a long-forgotten cybercity and find their way home.',12,'..\\..\\images\\stray.jpg'),(1364780,'Street Fighter 6','CAPCOM Co., Ltd.',3999,'Action, Adventure','2023-06-01','Here comes Capcom’s newest challenger! Street Fighter™ 6 launches worldwide on June 2nd, 2023 and represents the next evolution of the Street Fighter™ series! Street Fighter 6 spans three distinct game modes, including World Tour, Fighting Ground and Battle Hub.',12,'..\\..\\images\\street_fighter_6.jpg'),(1372280,'MELTY BLOOD: TYPE LUMINA','FRENCH-BREAD, TYPE-MOON, Lasengle Inc., TAMSOFT CORPORATION, GameLoop Inc.',4999,'Action','2021-09-29','This is the latest addition to the series of 2D fighting games based on TYPE-MOON\'s visual novel, Tsukihime. The curtain rises once more on dramatic battles played out with familiar characters from Tsukihime: A Piece of Blue Glass Moon.',12,'..\\..\\images\\melty_blood__type_lumina.jpg'),(1407200,'World of Tanks','Wargaming Group Limited',0,'Action, Massively Multiplayer, Simulation, Free To Play','2021-04-28','World of Tanks is a tactical action game with very different gameplay depending on the vehicle type and role. Aside from regular PvP, there are competitive and clan-based modes, special PvE and PvPvE events, and much more. Whether you play to dominate or just enjoy the ride, you\'ll fit right in.',12,'..\\..\\images\\world_of_tanks.jpg'),(1457080,'The Mageseeker: A League of Legends Story','Digital Sun',2999,'Action, Indie, RPG','2023-04-18','From Digital Sun, creators of Moonlighter, The Mageseeker is an action RPG in the League of Legends universe. Play as Sylas, a mage now freed from years in captivity. Wield the chains that once bound you and liberate Demacia from the Mageseekers\' tyranny.',12,'..\\..\\images\\the_mageseeker__a_league_of_legends_story.jpg'),(1485590,'ENDLESS Dungeon - Definitive Edition','AMPLITUDE Studios',1499,'Action, Strategy','2023-10-19','ENDLESS™ Dungeon is a Rogue-lite Tactical Action game, set in the award-winning ENDLESS™ Universe. Recruit a team of shipwrecked heroes, plunge into a long-abandoned space station, and protect your crystal against never-ending waves of monsters… or die trying, get reloaded, and try again.',12,'..\\..\\images\\endless_dungeon___definitive_edition.jpg'),(1627720,'Lies of P','NEOWIZ',2999,'Action, Adventure, RPG','2023-09-18','Lies of P is a thrilling soulslike that takes the story of Pinocchio, turns it on its head, and sets it against the darkly elegant backdrop of the Belle Epoque era.',16,'..\\..\\images\\lies_of_p.jpg'),(1778820,'TEKKEN 8','Bandai Namco Studios Inc.',5999,'Action','2024-01-25','TEKKEN 8 is the latest addition to the TEKKEN series, the pinnacle of 3D fighting games. Join the fight with over 32 characters and bear witness to the next installment in this epic saga. Get ready for the biggest and best TEKKEN game ever made!',16,'..\\..\\images\\tekken_8.jpg'),(1818750,'MultiVersus','Player First Games',0,'Action, Free To Play','2022-07-19','MultiVersus is a free-to-play platform fighter that brings the depth of iconic WB stars to life across the nearly endless possibilities of play.',12,'..\\..\\images\\multiversus.jpg'),(1895880,'Ratchet & Clank: Rift Apart','Insomniac Games, Nixxes Software',5999,'Action, Adventure','2023-07-26','Blast your way through an interdimensional adventure with Ratchet and Clank – now on PC! Help them take on an evil emperor from another reality as you jump between action-packed worlds and beyond at hyper-speed!',7,'..\\..\\images\\ratchet___clank__rift_apart.jpg'),(1903340,'Clair Obscur: Expedition 33','Sandfall Interactive',4999,'Action, RPG','2025-04-24','Lead the members of Expedition 33 on their quest to destroy the Paintress so that she can never paint death again. Explore a world of wonders inspired by Belle Époque France and battle unique enemies in this turn-based RPG with real-time mechanics.',18,'..\\..\\images\\clair_obscur__expedition_33.jpg'),(2071280,'Ravenswatch','Passtech Games',2499,'Action, Adventure','2024-09-26','Fallen heroes of old folk tales and legends: you are on the verge of a crucial battle against the Nightmare invading and corrupting your world. A roguelike action game from the creators of Curse of the Dead Gods©, playable solo or in online co-op.',18,'..\\..\\images\\ravenswatch.jpg'),(2357570,'Overwatch 2','Blizzard Entertainment, Inc.',0,'Action, Free To Play','2023-08-10','Overwatch 2 is a critically acclaimed, team-based shooter game set in an optimistic future with an evolving roster of heroes. Team up with friends and jump in today.',12,'..\\..\\images\\overwatch_2.jpg'),(2622380,'ELDEN RING NIGHTREIGN','FromSoftware, Inc.',3999,'Action, RPG','2025-05-29','ELDEN RING NIGHTREIGN is a standalone adventure within the ELDEN RING universe, crafted to offer players a new gaming experience by reimagining the game’s core design.',16,'..\\..\\images\\elden_ring_nightreign.jpg'),(3105370,'The Casting of Frank Stone Demo','Supermassive Games',0,'','2024-08-26','The shadow of Frank Stone looms over Cedar Hills, a town forever altered by his violent past. As a group of young friends are about to discover, Stone’s blood-soaked legacy cuts deep, leaving scars across families, generations, and the very fabric of reality itself.',18,'..\\..\\images\\the_casting_of_frank_stone_demo.jpg');
